/// 按名字取编译期生成的声明表；名字不在表里时返回 `None`。
pub fn declared(name: &str) -> Option<&'static Table> {
    tables()
        .iter()
        .find(|(entry, _)| *entry == name)
        .map(|(_, table)| table)
}

